+++ b/apps/frontend/src/api/http.test.ts
@@ -0,0 +1,238 @@
+import { HttpResponse, delay, http as mswHttp } from 'msw';
+import { describe, expect, it, vi } from 'vitest';
+import { server } from '../test/server';
+import {
+  ApiError,
+  CODIGO_ERROR_HTTP,
+  CODIGO_ERROR_RED,
+  createHttpClient,
+  esErrorDto,
+  type FetchFn,
+} from './http';
+import { createTokenStore } from './tokenStore';
+
+const BASE = 'http://api.test/api/v1';
+
+const noAutenticado = () =>
+  HttpResponse.json({ codigo: 'NO_AUTENTICADO', mensaje: 'Token inválido o expirado.' }, { status: 401 });
+
+async function capturarError(promesa: Promise<unknown>): Promise<ApiError> {
+  try {
+    await promesa;
+  } catch (error) {
+    if (error instanceof ApiError) return error;
+    throw error;
+  }
+  throw new Error('Se esperaba que la petición fallara');
+}
+
+describe('cliente HTTP: reintento tras 401 vía /auth/refresh', () => {
+  it('renueva el access token y reintenta una sola vez la petición original', async () => {
+    const tokenStore = createTokenStore('viejo');
+    const autorizaciones: (string | null)[] = [];
+    let refreshes = 0;
+    server.use(
+      mswHttp.get(`${BASE}/recurso`, ({ request }) => {
+        const autorizacion = request.headers.get('Authorization');
+        autorizaciones.push(autorizacion);
+        return autorizacion === 'Bearer nuevo' ? HttpResponse.json({ ok: true }) : noAutenticado();
+      }),
+      mswHttp.post(`${BASE}/auth/refresh`, () => {
+        refreshes += 1;
+        return HttpResponse.json({ accessToken: 'nuevo' });
+      }),
+    );
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore });
+
+    await expect(cliente.get('/recurso')).resolves.toEqual({ ok: true });
+
+    expect(refreshes).toBe(1);
+    expect(autorizaciones).toEqual(['Bearer viejo', 'Bearer nuevo']);
+    expect(tokenStore.get()).toBe('nuevo');
+  });
+
+  it('si el refresh falla limpia el token y propaga el 401 original sin reintentar', async () => {
+    const tokenStore = createTokenStore('viejo');
+    let llamadas = 0;
+    server.use(
+      mswHttp.get(`${BASE}/recurso`, () => {
+        llamadas += 1;
+        return noAutenticado();
+      }),
+      mswHttp.post(`${BASE}/auth/refresh`, () =>
+        HttpResponse.json({ codigo: 'NO_AUTENTICADO', mensaje: 'Sesión revocada.' }, { status: 401 }),
+      ),
+    );
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore });
+
+    const error = await capturarError(cliente.get('/recurso'));
+
+    expect(error.status).toBe(401);
+    expect(error.codigo).toBe('NO_AUTENTICADO');
+    expect(llamadas).toBe(1);
+    expect(tokenStore.get()).toBeNull();
+  });
+
+  it('no entra en bucle: si el reintento vuelve a dar 401 falla tras un único refresh', async () => {
+    const tokenStore = createTokenStore('viejo');
+    let llamadas = 0;
+    let refreshes = 0;
+    server.use(
+      mswHttp.get(`${BASE}/recurso`, () => {
+        llamadas += 1;
+        return noAutenticado();
+      }),
+      mswHttp.post(`${BASE}/auth/refresh`, () => {
+        refreshes += 1;
+        return HttpResponse.json({ accessToken: 'nuevo' });
+      }),
+    );
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore });
+
+    const error = await capturarError(cliente.get('/recurso'));
+
+    expect(error.status).toBe(401);
+    expect(llamadas).toBe(2);
+    expect(refreshes).toBe(1);
+  });
+
+  it('comparte un único refresh entre peticiones concurrentes que reciben 401', async () => {
+    const tokenStore = createTokenStore('viejo');
+    let refreshes = 0;
+    server.use(
+      mswHttp.get(`${BASE}/recurso/:id`, ({ request, params }) =>
+        request.headers.get('Authorization') === 'Bearer nuevo'
+          ? HttpResponse.json({ id: params.id })
+          : noAutenticado(),
+      ),
+      mswHttp.post(`${BASE}/auth/refresh`, async () => {
+        refreshes += 1;
+        await delay(50);
+        return HttpResponse.json({ accessToken: 'nuevo' });
+      }),
+    );
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore });
+
+    const resultados = await Promise.all([cliente.get('/recurso/1'), cliente.get('/recurso/2')]);
+
+    expect(resultados).toEqual([{ id: '1' }, { id: '2' }]);
+    expect(refreshes).toBe(1);
+  });
+
+  it('no intenta refresh si la petición no llevaba access token', async () => {
+    let refreshes = 0;
+    server.use(
+      mswHttp.get(`${BASE}/recurso`, noAutenticado),
+      mswHttp.post(`${BASE}/auth/refresh`, () => {
+        refreshes += 1;
+        return HttpResponse.json({ accessToken: 'nuevo' });
+      }),
+    );
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore: createTokenStore() });
+
+    const error = await capturarError(cliente.get('/recurso'));
+
+    expect(error.status).toBe(401);
+    expect(refreshes).toBe(0);
+  });
+
+  it('no intenta refresh cuando la petición pide sinReintento', async () => {
+    let refreshes = 0;
+    server.use(
+      mswHttp.post(`${BASE}/auth/login`, noAutenticado),
+      mswHttp.post(`${BASE}/auth/refresh`, () => {
+        refreshes += 1;
+        return HttpResponse.json({ accessToken: 'nuevo' });
+      }),
+    );
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore: createTokenStore('viejo') });
+
+    await expect(cliente.post('/auth/login', {}, { sinReintento: true })).rejects.toBeInstanceOf(ApiError);
+    expect(refreshes).toBe(0);
+  });
+
+  it('refrescarSesion devuelve false y limpia el token si la respuesta no trae accessToken', async () => {
+    const tokenStore = createTokenStore('viejo');
+    server.use(mswHttp.post(`${BASE}/auth/refresh`, () => HttpResponse.json({})));
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore });
+
+    await expect(cliente.refrescarSesion()).resolves.toBe(false);
+    expect(tokenStore.get()).toBeNull();
+  });
+});
+
+describe('cliente HTTP: parseo de errores (ErrorDto)', () => {
+  it('convierte un ErrorDto en ApiError con status, código, mensaje y campos', async () => {
+    server.use(
+      mswHttp.post(`${BASE}/registro`, () =>
+        HttpResponse.json(
+          { codigo: 'CORREO_DUPLICADO', mensaje: 'El correo ya está registrado.', campos: { correo: ['duplicado'] } },
+          { status: 409 },
+        ),
+      ),
+    );
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore: createTokenStore() });
+
+    const error = await capturarError(cliente.post('/registro', { correo: 'a@b.mx' }));
+
+    expect(error.status).toBe(409);
+    expect(error.codigo).toBe('CORREO_DUPLICADO');
+    expect(error.message).toBe('El correo ya está registrado.');
+    expect(error.campos).toEqual({ correo: ['duplicado'] });
+  });
+
+  it('usa ERROR_HTTP cuando el cuerpo del error no es un ErrorDto', async () => {
+    server.use(mswHttp.get(`${BASE}/recurso`, () => new HttpResponse('Bad gateway', { status: 502 })));
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore: createTokenStore() });
+
+    const error = await capturarError(cliente.get('/recurso'));
+
+    expect(error.status).toBe(502);
+    expect(error.codigo).toBe(CODIGO_ERROR_HTTP);
+  });
+
+  it('usa ERROR_RED con status 0 cuando no hay conexión', async () => {
+    server.use(mswHttp.get(`${BASE}/recurso`, () => HttpResponse.error()));
+    const cliente = createHttpClient({ baseUrl: BASE, tokenStore: createTokenStore() });
+
+    const error = await capturarError(cliente.get('/recurso'));
+
+    expect(error.status).toBe(0);
+    expect(error.codigo).toBe(CODIGO_ERROR_RED);
+  });
+
+  it('esErrorDto solo acepta objetos con codigo y mensaje de texto', () => {
+    expect(esErrorDto({ codigo: 'X', mensaje: 'y' })).toBe(true);
+    expect(esErrorDto({ codigo: 'X' })).toBe(false);
+    expect(esErrorDto('texto')).toBe(false);
+    expect(esErrorDto(null)).toBe(false);
+  });
+});
+
+describe('cliente HTTP: armado de la petición', () => {
+  it('usa la URL base, credentials include, JSON y el header Authorization desde memoria', async () => {
+    const fetchFn = vi.fn<FetchFn>().mockResolvedValue(Response.json({ id: 1 }, { status: 201 }));
+    const cliente = createHttpClient({ baseUrl: `${BASE}/`, tokenStore: createTokenStore('abc'), fetchFn });
+
