--- /dev/null
+++ b/apps/frontend/src/api/http.ts
@@ -0,0 +1,199 @@
+import type { components } from './schema';
+import { createTokenStore, type TokenStore } from './tokenStore';
+
+/** Formato uniforme de error de la API (generado desde /api/docs-json). */
+export type ErrorDto = components['schemas']['ErrorDto'];
+
+/** Código que usa el cliente cuando no hubo respuesta del servidor (sin conexión, CORS, DNS…). */
+export const CODIGO_ERROR_RED = 'ERROR_RED';
+/** Código que usa el cliente cuando la respuesta de error no trae un ErrorDto. */
+export const CODIGO_ERROR_HTTP = 'ERROR_HTTP';
+export const REFRESH_PATH = '/auth/refresh';
+
+export class ApiError extends Error {
+  readonly status: number;
+  readonly codigo: string;
+  readonly campos?: Record<string, string[]>;
+
+  constructor(status: number, dto: ErrorDto) {
+    super(dto.mensaje);
+    this.name = 'ApiError';
+    this.status = status;
+    this.codigo = dto.codigo;
+    this.campos = dto.campos;
+  }
+}
+
+export function esErrorDto(valor: unknown): valor is ErrorDto {
+  if (typeof valor !== 'object' || valor === null) return false;
+  const candidato = valor as Record<string, unknown>;
+  return typeof candidato.codigo === 'string' && typeof candidato.mensaje === 'string';
+}
+
+export type MetodoHttp = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
+
+export interface OpcionesPeticion {
+  method?: MetodoHttp;
+  /** Se envía como JSON salvo que sea FormData. */
+  body?: unknown;
+  headers?: Record<string, string>;
+  signal?: AbortSignal;
+  /** Desactiva el reintento vía /auth/refresh ante un 401 (p. ej. en el propio login). */
+  sinReintento?: boolean;
+}
+
+type OpcionesSinCuerpo = Omit<OpcionesPeticion, 'method' | 'body'>;
+
+export interface HttpClient {
+  request<T>(path: string, opciones?: OpcionesPeticion): Promise<T>;
+  get<T>(path: string, opciones?: OpcionesSinCuerpo): Promise<T>;
+  post<T>(path: string, body?: unknown, opciones?: OpcionesSinCuerpo): Promise<T>;
+  put<T>(path: string, body?: unknown, opciones?: OpcionesSinCuerpo): Promise<T>;
+  patch<T>(path: string, body?: unknown, opciones?: OpcionesSinCuerpo): Promise<T>;
+  delete<T>(path: string, opciones?: OpcionesSinCuerpo): Promise<T>;
+  /**
+   * Rota el refresh token (cookie httpOnly) y guarda el nuevo access token en memoria.
+   * Las llamadas concurrentes comparten la misma petición. Devuelve false (y limpia el token) si falla.
+   */
+  refrescarSesion(): Promise<boolean>;
+}
+
+/** Subconjunto de fetch que usa el cliente; se inyecta en pruebas. */
+export type FetchFn = (url: string, init?: RequestInit) => Promise<Response>;
+
+export interface HttpClientConfig {
+  /** URL base de la API, p. ej. http://localhost:3000/api/v1 (VITE_API_BASE_URL). */
+  baseUrl: string;
+  tokenStore: TokenStore;
+  fetchFn?: FetchFn;
+}
+
+async function leerCuerpo(respuesta: Response): Promise<unknown> {
+  const texto = await respuesta.text();
+  if (!texto) return undefined;
+  try {
+    return JSON.parse(texto) as unknown;
+  } catch {
+    return texto;
+  }
+}
+
+function esAbort(error: unknown): boolean {
+  return typeof error === 'object' && error !== null && (error as { name?: unknown }).name === 'AbortError';
+}
+
+export function createHttpClient({
+  baseUrl,
+  tokenStore,
+  // Se resuelve en cada llamada para usar el fetch global vigente (p. ej. el interceptado por MSW en pruebas).
+  fetchFn = (url, init) => fetch(url, init),
+}: HttpClientConfig): HttpClient {
+  const base = baseUrl.replace(/\/+$/, '');
+  const urlDe = (path: string) => `${base}${path.startsWith('/') ? path : `/${path}`}`;
+  let refreshEnCurso: Promise<boolean> | null = null;
+
+  async function ejecutar(path: string, opciones: OpcionesPeticion): Promise<Response> {
+    const headers = new Headers(opciones.headers);
+    if (!headers.has('Accept')) headers.set('Accept', 'application/json');
+
+    let body: BodyInit | undefined;
+    if (opciones.body !== undefined) {
+      if (opciones.body instanceof FormData) {
+        body = opciones.body;
+      } else {
+        body = JSON.stringify(opciones.body);
+        headers.set('Content-Type', 'application/json');
+      }
+    }
+
+    const token = tokenStore.get();
+    if (token) headers.set('Authorization', `Bearer ${token}`);
+
+    try {
+      return await fetchFn(urlDe(path), {
+        method: opciones.method ?? 'GET',
+        headers,
+        body,
+        credentials: 'include',
+        signal: opciones.signal,
+      });
+    } catch (error) {
+      if (esAbort(error)) throw error;
+      throw new ApiError(0, {
+        codigo: CODIGO_ERROR_RED,
+        mensaje: 'No fue posible conectar con el servidor.',
+      });
+    }
+  }
+
+  async function ejecutarRefresh(): Promise<boolean> {
+    try {
+      const respuesta = await fetchFn(urlDe(REFRESH_PATH), {
+        method: 'POST',
+        headers: { Accept: 'application/json' },
+        credentials: 'include',
+      });
+      const cuerpo = respuesta.ok ? await leerCuerpo(respuesta) : undefined;
+      const accessToken =
+        typeof cuerpo === 'object' && cuerpo !== null ? (cuerpo as { accessToken?: unknown }).accessToken : undefined;
+      if (typeof accessToken !== 'string' || accessToken === '') {
+        tokenStore.clear();
+        return false;
+      }
+      tokenStore.set(accessToken);
+      return true;
+    } catch {
+      tokenStore.clear();
+      return false;
+    }
+  }
+
+  function refrescarSesion(): Promise<boolean> {
+    if (!refreshEnCurso) {
+      refreshEnCurso = ejecutarRefresh().finally(() => {
+        refreshEnCurso = null;
+      });
+    }
+    return refreshEnCurso;
+  }
+
+  async function request<T>(path: string, opciones: OpcionesPeticion = {}): Promise<T> {
+    const llevabaToken = tokenStore.get() !== null;
+    let respuesta = await ejecutar(path, opciones);
+
+    // Un único reintento: si el access token expiró se renueva con la cookie y se repite la petición.
+    if (respuesta.status === 401 && llevabaToken && !opciones.sinReintento && path !== REFRESH_PATH) {
+      if (await refrescarSesion()) {
+        respuesta = await ejecutar(path, opciones);
+      }
+    }
+
+    const cuerpo = await leerCuerpo(respuesta);
+    if (!respuesta.ok) {
+      throw new ApiError(
+        respuesta.status,
+        esErrorDto(cuerpo) ? cuerpo : { codigo: CODIGO_ERROR_HTTP, mensaje: `Error HTTP ${respuesta.status}` },
+      );
+    }
+    return cuerpo as T;
+  }
+
+  return {
+    request,
+    get: (path, opciones) => request(path, { ...opciones, method: 'GET' }),
+    post: (path, body, opciones) => request(path, { ...opciones, method: 'POST', body }),
+    put: (path, body, opciones) => request(path, { ...opciones, method: 'PUT', body }),
+    patch: (path, body, opciones) => request(path, { ...opciones, method: 'PATCH', body }),
+    delete: (path, opciones) => request(path, { ...opciones, method: 'DELETE' }),
+    refrescarSesion,
+  };
+}
+
+/** Access token de la sesión actual, solo en memoria. Lo comparten el cliente HTTP y AuthContext. */
+export const accessTokenStore = createTokenStore();
+
+/** Cliente HTTP de la aplicación. */
+export const http = createHttpClient({
+  baseUrl: import.meta.env.VITE_API_BASE_URL ?? '',
+  tokenStore: accessTokenStore,
+});
