+import { describe, expect, it, vi } from 'vitest';
+import { createTokenStore } from './tokenStore';
+
+describe('createTokenStore', () => {
+  it('empieza vacío o con el token inicial indicado', () => {
+    expect(createTokenStore().get()).toBeNull();
+    expect(createTokenStore('abc').get()).toBe('abc');
+  });
+
+  it('guarda y limpia el token en memoria notificando a los suscriptores', () => {
+    const store = createTokenStore();
+    const listener = vi.fn();
+    store.subscribe(listener);
+
+    store.set('abc');
+    expect(store.get()).toBe('abc');
+    store.clear();
+    expect(store.get()).toBeNull();
+
+    expect(listener).toHaveBeenCalledTimes(2);
+  });
+
+  it('no notifica si el token no cambia', () => {
+    const store = createTokenStore('abc');
+    const listener = vi.fn();
+    store.subscribe(listener);
+
+    store.set('abc');
+
+    expect(listener).not.toHaveBeenCalled();
+  });
+
+  it('deja de notificar al cancelar la suscripción', () => {
+    const store = createTokenStore();
+    const listener = vi.fn();
+    const cancelar = store.subscribe(listener);
+
+    cancelar();
+    store.set('abc');
+
+    expect(listener).not.toHaveBeenCalled();
+  });
+});
