@@ -0,0 +1,36 @@
+type Listener = () => void;
+
+/**
+ * Almacén en memoria del access token. Nunca se persiste (ni localStorage ni sessionStorage): al recargar la
+ * página la sesión se recupera con el refresh token de la cookie httpOnly.
+ * La API (subscribe/get) es compatible con useSyncExternalStore.
+ */
+export interface TokenStore {
+  get(): string | null;
+  set(token: string | null): void;
+  clear(): void;
+  subscribe(listener: Listener): () => void;
+}
+
+export function createTokenStore(inicial: string | null = null): TokenStore {
+  let token = inicial;
+  const listeners = new Set<Listener>();
+
+  const set = (nuevo: string | null) => {
+    if (nuevo === token) return;
+    token = nuevo;
+    listeners.forEach((listener) => listener());
+  };
+
+  return {
+    get: () => token,
+    set,
+    clear: () => set(null),
+    subscribe: (listener) => {
+      listeners.add(listener);
+      return () => {
+        listeners.delete(listener);
+      };
+    },
+  };
+}
