+import { describe, expect, it } from 'vitest';
+import { ApiError } from '../api/http';
+import { createQueryClient, debeReintentar } from './queryClient';
+
+describe('queryClient', () => {
+  it('no reintenta errores 4xx de la API', () => {
+    expect(debeReintentar(0, new ApiError(404, { codigo: 'NO_ENCONTRADO', mensaje: 'x' }))).toBe(false);
+  });
+
+  it('reintenta una sola vez errores de red o 5xx', () => {
+    const error = new ApiError(503, { codigo: 'SERVICIO_NO_DISPONIBLE', mensaje: 'x' });
+
+    expect(debeReintentar(0, error)).toBe(true);
+    expect(debeReintentar(1, error)).toBe(false);
+    expect(debeReintentar(0, new Error('red'))).toBe(true);
+  });
+
+  it('crea clientes independientes con la política por defecto', () => {
+    const cliente = createQueryClient();
+
+    expect(cliente).not.toBe(createQueryClient());
+    expect(cliente.getDefaultOptions().queries?.retry).toBe(debeReintentar);
+    expect(cliente.getDefaultOptions().mutations?.retry).toBe(false);
+  });
+});
