@@ -0,0 +1,28 @@
+import { QueryClient } from '@tanstack/react-query';
+import { ApiError } from '../api/http';
+
+/** Los errores 4xx son definitivos (validación, permisos, no encontrado): solo se reintenta una vez lo demás. */
+export function debeReintentar(intentosFallidos: number, error: unknown): boolean {
+  if (error instanceof ApiError && error.status >= 400 && error.status < 500) {
+    return false;
+  }
+  return intentosFallidos < 1;
+}
+
+export function createQueryClient(): QueryClient {
+  return new QueryClient({
+    defaultOptions: {
+      queries: {
+        retry: debeReintentar,
+        refetchOnWindowFocus: false,
+        staleTime: 30_000,
+      },
+      mutations: {
+        retry: false,
+      },
+    },
+  });
+}
+
+/** QueryClient de la aplicación (estado del servidor). */
+export const queryClient = createQueryClient();
