+import { screen } from '@testing-library/react';
+import { describe, expect, it } from 'vitest';
+import type { Usuario } from '../auth/types';
+import { renderRuta } from '../test/renderRuta';
+import { RUTAS } from './rutas';
+
+const cliente: Usuario = { id: 'u1', correo: 'cliente@correo.mx', rol: 'CLIENTE' };
+const recepcion: Usuario = { id: 'u2', correo: 'recepcion@taller.mx', rol: 'RECEPCION' };
+
+describe('router', () => {
+  it.each([
+    [RUTAS.login, 'Iniciar sesión'],
+    [RUTAS.registro, 'Crear cuenta'],
+    [RUTAS.verificarCorreo, 'Verificación de correo'],
+    [RUTAS.olvideContrasena, 'Olvidé mi contraseña'],
+    [RUTAS.restablecer, 'Restablecer contraseña'],
+  ])('muestra la ruta pública %s dentro del layout público', async (ruta, titulo) => {
+    renderRuta(ruta);
+
+    expect(await screen.findByRole('heading', { level: 1, name: titulo })).toBeInTheDocument();
+    expect(screen.getByRole('banner')).toHaveTextContent('ITZ Agenda Taller');
+  });
+
+  it('muestra la página 404 en una ruta desconocida', async () => {
+    renderRuta('/no-existe');
+
+    expect(await screen.findByRole('heading', { level: 1, name: 'Página no encontrada' })).toBeInTheDocument();
+    expect(screen.getByRole('link', { name: 'Ir al inicio' })).toHaveAttribute('href', RUTAS.raiz);
+  });
+
+  it('redirige al login al entrar anónimo a una ruta protegida', async () => {
+    const { router } = renderRuta(RUTAS.misVehiculos);
+
+    expect(await screen.findByRole('heading', { level: 1, name: 'Iniciar sesión' })).toBeInTheDocument();
+    expect(router.state.location.pathname).toBe(RUTAS.login);
+  });
+
+  it('muestra Mis vehículos al CLIENTE dentro del layout autenticado', async () => {
+    renderRuta(RUTAS.misVehiculos, { usuario: cliente });
+
+    expect(await screen.findByRole('heading', { level: 1, name: 'Mis vehículos' })).toBeInTheDocument();
+    expect(screen.getByRole('banner')).toHaveTextContent(cliente.correo);
+  });
+
+  it('manda al CLIENTE a su ruta inicial si entra al área interna', async () => {
+    const { router } = renderRuta(RUTAS.interno, { usuario: cliente });
+
+    expect(await screen.findByRole('heading', { level: 1, name: 'Mis vehículos' })).toBeInTheDocument();
+    expect(router.state.location.pathname).toBe(RUTAS.misVehiculos);
+  });
+
+  it('muestra el inicio interno al personal de RECEPCION y le impide entrar a Mis vehículos', async () => {
+    const { router } = renderRuta(RUTAS.misVehiculos, { usuario: recepcion });
+
+    expect(await screen.findByRole('heading', { level: 1, name: 'Inicio del personal' })).toBeInTheDocument();
+    expect(router.state.location.pathname).toBe(RUTAS.interno);
+  });
+
+  it('redirige la raíz al login si no hay sesión y a la ruta inicial del rol si la hay', async () => {
+    const anonimo = renderRuta(RUTAS.raiz);
+    expect(await screen.findByRole('heading', { level: 1, name: 'Iniciar sesión' })).toBeInTheDocument();
+    expect(anonimo.router.state.location.pathname).toBe(RUTAS.login);
+    anonimo.unmount();
+
