+import { createBrowserRouter, type RouteObject } from 'react-router-dom';
+import { RedireccionInicial } from '../auth/RedireccionInicial';
+import { RequireAuth } from '../auth/RequireAuth';
+import { RequireRole } from '../auth/RequireRole';
+import { MisVehiculosPage } from '../features/cliente/MisVehiculosPage';
+import { InicioInternoPage } from '../features/interno/InicioInternoPage';
+import { LoginPage } from '../features/login/pages/LoginPage';
+import { OlvideContrasenaPage } from '../features/password-recovery/pages/OlvideContrasenaPage';
+import { RestablecerPage } from '../features/password-recovery/pages/RestablecerPage';
+import { RegistroPage } from '../features/registro/pages/RegistroPage';
+import { VerificarCorreoPage } from '../features/registro/pages/VerificarCorreoPage';
+import { NotFoundPage } from '../shared/components/NotFoundPage';
+import { AuthenticatedLayout } from './layouts/AuthenticatedLayout';
+import { PublicLayout } from './layouts/PublicLayout';
+import { RUTAS } from './rutas';
+
+export const routes: RouteObject[] = [
+  { path: RUTAS.raiz, element: <RedireccionInicial /> },
+  {
+    element: <PublicLayout />,
+    children: [
+      { path: RUTAS.login, element: <LoginPage /> },
+      { path: RUTAS.registro, element: <RegistroPage /> },
+      { path: RUTAS.verificarCorreo, element: <VerificarCorreoPage /> },
+      { path: RUTAS.olvideContrasena, element: <OlvideContrasenaPage /> },
+      { path: RUTAS.restablecer, element: <RestablecerPage /> },
+      { path: '*', element: <NotFoundPage /> },
+    ],
+  },
+  {
+    element: (
+      <RequireAuth>
+        <AuthenticatedLayout />
+      </RequireAuth>
+    ),
+    children: [
+      {
+        element: <RequireRole roles={['CLIENTE']} />,
+        children: [{ path: RUTAS.misVehiculos, element: <MisVehiculosPage /> }],
+      },
+      {
+        element: <RequireRole roles={['RECEPCION', 'ADMIN']} />,
+        children: [{ path: RUTAS.interno, element: <InicioInternoPage /> }],
+      },
+    ],
+  },
+];
+
+export function crearRouter() {
+  return createBrowserRouter(routes);
+}
