+    expect(screen.getByTestId('estado')).toHaveTextContent('anonimo');
+    expect(screen.getByTestId('correo')).toHaveTextContent('-');
+  });
+
+  it('iniciarSesion guarda el access token solo en memoria y cerrarSesion lo borra', () => {
