+    fireEvent.click(screen.getByRole('button', { name: 'entrar' }));
+    expect(screen.getByTestId('estado')).toHaveTextContent('autenticado');
+    expect(screen.getByTestId('correo')).toHaveTextContent(cliente.correo);
+    expect(tokenStore.get()).toBe('token-1');
+    expect(window.localStorage.length).toBe(0);
+    expect(window.sessionStorage.length).toBe(0);
+
+    fireEvent.click(screen.getByRole('button', { name: 'salir' }));
+    expect(screen.getByTestId('estado')).toHaveTextContent('anonimo');
+    expect(tokenStore.get()).toBeNull();
+  });
+
+  it('refleja el token renovado por el cliente HTTP y pasa a anónimo si este lo limpia', () => {
+    const tokenStore = createTokenStore('token-1');
+    render(
+      <AuthProvider tokenStore={tokenStore} usuarioInicial={cliente}>
+        <EstadoAuth />
+      </AuthProvider>,
