+import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore, type ReactNode } from 'react';
+import { accessTokenStore } from '../api/http';
+import type { TokenStore } from '../api/tokenStore';
+import type { AuthContextValue, EstadoAuth, Sesion, Usuario } from './types';
+import { AuthContext } from './useAuth';
+
+export interface AuthProviderProps {
+  children: ReactNode;
+  /** Almacén del access token (en memoria); por defecto el que comparte el cliente HTTP. */
+  tokenStore?: TokenStore;
+  /** Usuario de una sesión ya presente en `tokenStore` (útil en pruebas). */
+  usuarioInicial?: Usuario | null;
+  /**
+   * Recupera la sesión al arrancar (p. ej. /auth/refresh + /auth/me con la cookie). Lo aporta la feature de
+   * login; sin él la app arranca anónima.
+   */
+  restaurarSesion?: () => Promise<Sesion | null>;
+}
+
+/**
+ * Estado de autenticación de la SPA. El access token vive solo en memoria (TokenStore); este contexto no
+ * implementa flujos de negocio (login, logout, refresh), solo guarda y expone la sesión.
+ */
+export function AuthProvider({
+  children,
+  tokenStore = accessTokenStore,
+  usuarioInicial = null,
+  restaurarSesion,
+}: AuthProviderProps) {
+  const [usuario, setUsuario] = useState<Usuario | null>(usuarioInicial);
+  const [restaurando, setRestaurando] = useState(restaurarSesion !== undefined);
+  // El cliente HTTP puede renovar o limpiar el token (refresh fallido): la sesión lo refleja al instante.
+  const accessToken = useSyncExternalStore(tokenStore.subscribe, tokenStore.get, tokenStore.get);
+  const restauracionIniciada = useRef(false);
+
+  const iniciarSesion = useCallback(
+    (sesion: Sesion) => {
+      tokenStore.set(sesion.accessToken);
+      setUsuario(sesion.usuario);
+    },
+    [tokenStore],
+  );
+
+  const cerrarSesion = useCallback(() => {
+    tokenStore.clear();
+    setUsuario(null);
+  }, [tokenStore]);
+
+  useEffect(() => {
+    // Una sola vez aunque StrictMode monte dos veces: el refresh token rota en cada uso.
+    if (!restaurarSesion || restauracionIniciada.current) return;
+    restauracionIniciada.current = true;
+    restaurarSesion()
+      .then((sesion) => {
+        if (sesion) iniciarSesion(sesion);
+      })
+      .catch(() => cerrarSesion())
+      .finally(() => setRestaurando(false));
+  }, [restaurarSesion, iniciarSesion, cerrarSesion]);
+
+  const autenticado = usuario !== null && accessToken !== null;
+  const estado: EstadoAuth = restaurando ? 'cargando' : autenticado ? 'autenticado' : 'anonimo';
+
+  const valor = useMemo<AuthContextValue>(
+    () => ({
+      estado,
+      usuario: autenticado ? usuario : null,
+      accessToken,
+      iniciarSesion,
+      cerrarSesion,
+    }),
+    [estado, autenticado, usuario, accessToken, iniciarSesion, cerrarSesion],
+  );
+
+  return <AuthContext.Provider value={valor}>{children}</AuthContext.Provider>;
+}
