+import type { ReactNode } from 'react';
+import { Navigate, Outlet, useLocation } from 'react-router-dom';
+import { RUTAS } from '../app/rutas';
+import { PantallaCargando } from '../shared/components/PantallaCargando';
+import { useAuth } from './useAuth';
+
+interface RequireAuthProps {
+  /** Contenido protegido; si se omite se renderizan las rutas hijas (<Outlet />). */
+  children?: ReactNode;
+}
+
+/** Solo deja pasar con sesión activa; si no, manda al login recordando la ruta de origen en `state.desde`. */
+export function RequireAuth({ children }: RequireAuthProps) {
+  const { estado } = useAuth();
+  const location = useLocation();
+
+  if (estado === 'cargando') {
+    return <PantallaCargando />;
+  }
+  if (estado !== 'autenticado') {
+    return <Navigate to={RUTAS.login} replace state={{ desde: location }} />;
+  }
+  return children ? <>{children}</> : <Outlet />;
+}
