+import type { ReactNode } from 'react';
+import { Navigate, Outlet } from 'react-router-dom';
+import { RUTAS } from '../app/rutas';
+import { rutaInicialPorRol } from './rutaInicialPorRol';
+import type { Rol } from './types';
+import { useAuth } from './useAuth';
+
+interface RequireRoleProps {
+  roles: readonly Rol[];
+  /** Contenido protegido; si se omite se renderizan las rutas hijas (<Outlet />). */
+  children?: ReactNode;
+}
+
+/**
+ * Solo deja pasar a los roles indicados; a los demás los manda a su ruta inicial.
+ * Se usa dentro de RequireAuth.
+ */
+export function RequireRole({ roles, children }: RequireRoleProps) {
+  const { usuario } = useAuth();
+
+  if (!usuario) {
+    return <Navigate to={RUTAS.login} replace />;
+  }
+  if (!roles.includes(usuario.rol)) {
+    return <Navigate to={rutaInicialPorRol(usuario.rol)} replace />;
+  }
+  return children ? <>{children}</> : <Outlet />;
+}
