+  apellidos: 'Pérez López',
+  correo: 'qa.e1@test.com',
+  celular: '5512345678',
+  whatsapp: '',
+  password: 'Taller2026',
+};
+type Datos = typeof DATOS_VALIDOS;
+
+const campo: Record<keyof Datos, () => HTMLElement> = {
+  nombres: () => screen.getByLabelText(/^Nombre\(s\)/),
+  apellidos: () => screen.getByLabelText(/^Apellidos/),
+  correo: () => screen.getByLabelText(/^Correo/),
+  celular: () => screen.getByLabelText(/^Celular/),
+  whatsapp: () => screen.getByLabelText(/^WhatsApp/),
+  password: () => screen.getByLabelText(/^Contraseña/),
+};
+const casillaAviso = () => screen.getByRole('checkbox', { name: 'Acepto el aviso de privacidad' });
+const casillaTerminos = () => screen.getByRole('checkbox', { name: 'Acepto los términos' });
+const botonCrear = () => screen.getByRole('button', { name: 'Crear cuenta' });
+
+const MENSAJE_AVISO = 'Debes aceptar el aviso de privacidad.';
+const MENSAJE_TERMINOS = 'Debes aceptar los términos y condiciones.';
+
+const registroExitoso = () =>
+  HttpResponse.json(
+    { id: 'u-1', correo: 'qa.e1@test.com', estado: 'PENDIENTE_VERIFICACION', correoVerificacionEnviado: true },
+    { status: 201 },
+  );
+
+type RespuestaMock = ReturnType<typeof HttpResponse.json>;
+
+/** Declara los handlers de la API y devuelve los cuerpos que recibe POST /registro. */
+function prepararApi(responder: () => RespuestaMock = registroExitoso): unknown[] {
+  const solicitudes: unknown[] = [];
+  server.use(
+    mswHttp.get(urlApi('/legal/documentos-vigentes'), () => HttpResponse.json(DOCUMENTOS)),
+    mswHttp.post(urlApi('/registro'), async ({ request }) => {
+      solicitudes.push(await request.json());
+      return responder();
+    }),
+  );
+  return solicitudes;
+}
+
+async function abrirRegistro() {
+  const render = renderRuta(RUTAS.registro);
+  await screen.findByRole('heading', { level: 1, name: 'Crear cuenta' });
+  return render;
+}
+
+async function llenar(
+  user: UserEvent,
+  datos: Partial<Datos> = {},
+  casillas: { aviso: boolean; terminos: boolean } = { aviso: true, terminos: true },
+) {
+  const valores = { ...DATOS_VALIDOS, ...datos };
+  for (const clave of Object.keys(valores) as (keyof Datos)[]) {
+    if (valores[clave] !== '') await user.type(campo[clave](), valores[clave]);
+  }
+  if (casillas.aviso) await user.click(casillaAviso());
+  if (casillas.terminos) await user.click(casillaTerminos());
+}
+
+describe('CrearCuentaPage: registro exitoso', () => {
