+    expect(await screen.findByRole('heading', { level: 1, name: 'Revisa tu correo' })).toBeInTheDocument();
+    expect(router.state.location.pathname).toBe(RUTAS.revisaTuCorreo);
+    expect(screen.getByText('qa.e1@test.com')).toBeInTheDocument();
+    expect(screen.getByRole('button', { name: 'Reenviar correo de verificación' })).toBeInTheDocument();
+    expect(solicitudes).toEqual([
+      {
+        nombres: 'Juan',
+        apellidos: 'Pérez López',
+        correo: 'qa.e1@test.com',
+        celular: '5512345678',
+        password: 'Taller2026',
+        aceptaAvisoPrivacidad: true,
+        aceptaTerminos: true,
+      },
+    ]);
+    expect(solicitudes[0]).not.toHaveProperty('whatsapp');
+  });
+
+  it('envía el WhatsApp capturado y el celular sin espacios ni guiones (TC-002)', async () => {
+    const solicitudes = prepararApi();
+    const user = userEvent.setup();
+    await abrirRegistro();
+
+    await llenar(user, { whatsapp: '5598765432', celular: '55 1234-5678' });
+    await user.click(botonCrear());
+
+    expect(await screen.findByRole('heading', { level: 1, name: 'Revisa tu correo' })).toBeInTheDocument();
+    expect(solicitudes[0]).toMatchObject({ celular: '5512345678', whatsapp: '5598765432' });
+  });
+
+  it('acepta la contraseña límite de exactamente 8 caracteres (TC-009)', async () => {
+    const solicitudes = prepararApi();
+    const user = userEvent.setup();
+    await abrirRegistro();
+
+    await llenar(user, { password: 'Abcdef12' });
