+
+    const enlaceTerminos = await screen.findByRole('link', { name: /Leer los términos/ });
+    expect(enlaceTerminos).toHaveAttribute('href', 'https://taller.test/terminos');
+    expect(enlaceTerminos).toHaveTextContent('versión 2.1');
+
+    await user.click(screen.getByRole('button', { name: /Leer el aviso de privacidad/ }));
+    const dialogo = await screen.findByRole('dialog');
+    expect(within(dialogo).getByText(/tus datos se usan para agendar/)).toBeInTheDocument();
+  });
+});
