+    ['sin los términos', { aviso: true, terminos: false }, [MENSAJE_TERMINOS], [MENSAJE_AVISO]],
+    ['sin ninguna casilla', { aviso: false, terminos: false }, [MENSAJE_AVISO, MENSAJE_TERMINOS], []],
+  ] as [string, { aviso: boolean; terminos: boolean }, string[], string[]][])(
