+
+  it.each(['551234567', '55123456789', '55123a5678', '+525512345678'])(
+    'rechaza el celular inválido %s (TC-023)',
+    async (celular) => {
+      const solicitudes = prepararApi();
+      const user = userEvent.setup();
+      await abrirRegistro();
+
+      await llenar(user, { celular });
+      await user.click(botonCrear());
+
+      const mensaje = 'El celular debe tener exactamente 10 dígitos numéricos.';
