+import { screen } from '@testing-library/react';
+import userEvent from '@testing-library/user-event';
+import { HttpResponse, http as mswHttp } from 'msw';
+import { describe, expect, it } from 'vitest';
+import { RUTAS } from '../../../app/rutas';
+import { urlApi } from '../../../test/api';
+import { renderRuta } from '../../../test/renderRuta';
+import { server } from '../../../test/server';
+
+const MENSAJE_NEUTRO = 'Si el correo tiene una cuenta pendiente de verificación, te enviaremos un nuevo enlace.';
+
+const reenvioAceptado = () => HttpResponse.json({ mensaje: MENSAJE_NEUTRO }, { status: 202 });
+
+type RespuestaMock = ReturnType<typeof HttpResponse.json>;
+
+/** Declara el handler del reenvío y devuelve los cuerpos que recibe. */
+function prepararReenvio(responder: () => RespuestaMock = reenvioAceptado): unknown[] {
+  const solicitudes: unknown[] = [];
+  server.use(
+    mswHttp.post(urlApi('/registro/reenviar-verificacion'), async ({ request }) => {
+      solicitudes.push(await request.json());
+      return responder();
+    }),
+  );
+  return solicitudes;
+}
+
+async function abrir(estado?: unknown) {
+  const render = renderRuta(RUTAS.revisaTuCorreo, { estado });
+  await screen.findByRole('heading', { level: 1, name: 'Revisa tu correo' });
+  return render;
+}
+
+const botonReenviar = () => screen.getByRole('button', { name: 'Reenviar correo de verificación' });
+
+describe('RevisaTuCorreoPage', () => {
+  it('indica a qué correo se envió el enlace y reenvía la verificación a ese correo', async () => {
+    const solicitudes = prepararReenvio();
+    const user = userEvent.setup();
+    await abrir({ correo: 'juan@test.com', correoVerificacionEnviado: true });
+
+    expect(screen.getByText('juan@test.com')).toBeInTheDocument();
+    expect(screen.queryByLabelText(/^Correo/)).not.toBeInTheDocument();
+
+    await user.click(botonReenviar());
+
+    expect(await screen.findByText(MENSAJE_NEUTRO)).toBeInTheDocument();
+    expect(solicitudes).toEqual([{ correo: 'juan@test.com' }]);
+  });
+
+  it('avisa si el correo de verificación no pudo enviarse y ofrece el reenvío (TC-034)', async () => {
+    const solicitudes = prepararReenvio();
+    const user = userEvent.setup();
+    await abrir({ correo: 'juan@test.com', correoVerificacionEnviado: false });
+
+    expect(screen.getByText(/No pudimos enviarte el correo de verificación/)).toBeInTheDocument();
+
+    await user.click(botonReenviar());
+
+    expect(await screen.findByText(MENSAJE_NEUTRO)).toBeInTheDocument();
+    expect(solicitudes).toHaveLength(1);
+  });
+
+  it('sin el correo en la navegación (p. ej. al recargar) lo pide y lo valida antes de reenviar', async () => {
+    const solicitudes = prepararReenvio();
+    const user = userEvent.setup();
+    await abrir();
+
+    await user.click(botonReenviar());
+    expect(await screen.findByText('El correo es obligatorio.')).toBeInTheDocument();
+
+    await user.type(screen.getByLabelText(/^Correo/), 'juan@');
+    await user.click(botonReenviar());
+    expect(await screen.findByText('El correo no tiene un formato válido.')).toBeInTheDocument();
+    expect(solicitudes).toHaveLength(0);
+
+    await user.clear(screen.getByLabelText(/^Correo/));
+    await user.type(screen.getByLabelText(/^Correo/), '  Juan@Test.com ');
+    await user.click(botonReenviar());
+
+    expect(await screen.findByText(MENSAJE_NEUTRO)).toBeInTheDocument();
+    expect(solicitudes).toEqual([{ correo: 'Juan@Test.com' }]);
+  });
+
+  it('traduce el error del backend cuando se excede el límite de reenvíos', async () => {
+    prepararReenvio(() =>
+      HttpResponse.json({ codigo: 'DEMASIADAS_SOLICITUDES', mensaje: 'Too many requests' }, { status: 429 }),
+    );
+    const user = userEvent.setup();
+    await abrir({ correo: 'juan@test.com', correoVerificacionEnviado: true });
+
+    await user.click(botonReenviar());
+
+    expect(
+      await screen.findByText('Demasiados intentos. Espera un momento e inténtalo de nuevo.'),
+    ).toBeInTheDocument();
+    expect(screen.queryByText(MENSAJE_NEUTRO)).not.toBeInTheDocument();
+  });
+
+  it('ofrece ir a iniciar sesión', async () => {
+    await abrir({ correo: 'juan@test.com', correoVerificacionEnviado: true });
+
+    expect(screen.getByRole('link', { name: 'Ir a iniciar sesión' })).toHaveAttribute('href', RUTAS.login);
+  });
+});
