+import Button from '@mui/material/Button';
+import Checkbox from '@mui/material/Checkbox';
+import Dialog from '@mui/material/Dialog';
+import DialogActions from '@mui/material/DialogActions';
+import DialogContent from '@mui/material/DialogContent';
+import DialogTitle from '@mui/material/DialogTitle';
+import FormControl from '@mui/material/FormControl';
+import FormControlLabel from '@mui/material/FormControlLabel';
+import FormHelperText from '@mui/material/FormHelperText';
+import Link from '@mui/material/Link';
+import Stack from '@mui/material/Stack';
+import Typography from '@mui/material/Typography';
+import { useId, useState } from 'react';
+import { Controller, type Control } from 'react-hook-form';
+import type { DocumentoLegal, TipoDocumentoLegal } from '../hooks/useDocumentosVigentesQuery';
+import type { ValoresRegistro } from '../registroSchema';
+
+interface DefinicionCasilla {
+  nombre: 'aceptaAvisoPrivacidad' | 'aceptaTerminos';
+  tipo: TipoDocumentoLegal;
+  etiqueta: string;
+  textoLeer: string;
+  tituloDocumento: string;
+}
+
+const CASILLAS: readonly DefinicionCasilla[] = [
+  {
+    nombre: 'aceptaAvisoPrivacidad',
+    tipo: 'AVISO_PRIVACIDAD',
+    etiqueta: 'Acepto el aviso de privacidad',
+    textoLeer: 'Leer el aviso de privacidad',
+    tituloDocumento: 'Aviso de privacidad',
+  },
+  {
+    nombre: 'aceptaTerminos',
+    tipo: 'TERMINOS',
+    etiqueta: 'Acepto los términos',
+    textoLeer: 'Leer los términos',
+    tituloDocumento: 'Términos y condiciones',
+  },
+];
+
+interface EnlaceDocumentoProps {
+  documento: DocumentoLegal;
+  textoLeer: string;
+  tituloDocumento: string;
+}
+
+/** Enlace al documento vigente: externo si tiene URL, o un diálogo con su contenido si se sirve desde el portal. */
+function EnlaceDocumento({ documento, textoLeer, tituloDocumento }: EnlaceDocumentoProps) {
+  const [abierto, setAbierto] = useState(false);
+  const idTitulo = useId();
+  const etiqueta = `${textoLeer} (versión ${documento.version})`;
+
+  if (documento.url) {
+    return (
+      <Link href={documento.url} target="_blank" rel="noopener noreferrer" variant="body2">
+        {etiqueta}
+      </Link>
+    );
+  }
+  if (!documento.contenido) {
+    return null;
+  }
+  return (
+    <>
+      <Link component="button" type="button" variant="body2" onClick={() => setAbierto(true)}>
+        {etiqueta}
+      </Link>
+      <Dialog open={abierto} onClose={() => setAbierto(false)} scroll="paper" aria-labelledby={idTitulo}>
+        <DialogTitle id={idTitulo}>
+          {tituloDocumento} (versión {documento.version})
+        </DialogTitle>
+        <DialogContent dividers>
+          <Typography variant="body2" sx={{ whiteSpace: 'pre-line' }}>
+            {documento.contenido}
+          </Typography>
+        </DialogContent>
+        <DialogActions>
+          <Button onClick={() => setAbierto(false)}>Cerrar</Button>
+        </DialogActions>
+      </Dialog>
+    </>
+  );
+}
+
+interface CasillaLegalProps {
+  control: Control<ValoresRegistro>;
+  casilla: DefinicionCasilla;
+  documento?: DocumentoLegal;
+}
+
+function CasillaLegal({ control, casilla, documento }: CasillaLegalProps) {
+  const idAyuda = useId();
+
+  return (
+    <Controller
+      control={control}
+      name={casilla.nombre}
+      render={({ field, fieldState }) => (
+        <FormControl error={fieldState.error !== undefined}>
+          <Stack direction="row" alignItems="center" flexWrap="wrap" columnGap={1}>
+            <FormControlLabel
+              label={casilla.etiqueta}
+              control={
+                <Checkbox
+                  name={field.name}
+                  checked={field.value}
+                  onChange={(evento) => field.onChange(evento.target.checked)}
+                  onBlur={field.onBlur}
+                  inputRef={field.ref}
+                  inputProps={{ 'aria-describedby': fieldState.error ? idAyuda : undefined }}
+                />
+              }
+            />
+            {documento && (
+              <EnlaceDocumento
+                documento={documento}
+                textoLeer={casilla.textoLeer}
+                tituloDocumento={casilla.tituloDocumento}
+              />
+            )}
+          </Stack>
+          {fieldState.error?.message && <FormHelperText id={idAyuda}>{fieldState.error.message}</FormHelperText>}
+        </FormControl>
+      )}
+    />
+  );
+}
+
+interface AceptacionLegalCheckboxesProps {
+  control: Control<ValoresRegistro>;
+  /** Documentos vigentes (GET /legal/documentos-vigentes); mientras cargan solo se muestran las casillas. */
+  documentos?: DocumentoLegal[];
+}
+
+/** Casillas obligatorias del aviso de privacidad y de los términos, con su mensaje de error junto a cada una. */
+export function AceptacionLegalCheckboxes({ control, documentos }: AceptacionLegalCheckboxesProps) {
+  return (
+    <Stack spacing={0.5}>
+      {CASILLAS.map((casilla) => (
+        <CasillaLegal
+          key={casilla.nombre}
+          control={control}
+          casilla={casilla}
+          documento={documentos?.find((documento) => documento.tipo === casilla.tipo)}
+        />
+      ))}
+    </Stack>
+  );
+}
