+import { zodResolver } from '@hookform/resolvers/zod';
+import Alert from '@mui/material/Alert';
+import Box from '@mui/material/Box';
+import Button from '@mui/material/Button';
+import Stack from '@mui/material/Stack';
+import TextField from '@mui/material/TextField';
+import Typography from '@mui/material/Typography';
+import { useForm } from 'react-hook-form';
+import { z } from 'zod';
+import { mensajeDeError } from '../../../shared/errors/mensajesError';
+import { correoSchema } from '../../../shared/validation/correo';
+import { useReenviarVerificacionMutation } from '../hooks/useReenviarVerificacionMutation';
+
+const reenvioSchema = z.object({ correo: correoSchema });
+type ValoresReenvio = z.input<typeof reenvioSchema>;
+
+/** Respuesta neutra por si el backend no la incluye (es la misma exista o no la cuenta). */
+const MENSAJE_REENVIO_POR_DEFECTO =
+  'Si el correo tiene una cuenta pendiente de verificación, te enviaremos un nuevo enlace.';
+
+interface ReenvioVerificacionProps {
+  /** Correo de la cuenta; si no se conoce (recarga o acceso directo) se le pide al usuario. */
+  correo?: string;
+}
+
+/** Botón "Reenviar correo de verificación" (POST /registro/reenviar-verificacion). */
+export function ReenvioVerificacion({ correo }: ReenvioVerificacionProps) {
+  const reenvio = useReenviarVerificacionMutation();
+  const {
+    register,
+    handleSubmit,
+    formState: { errors },
+  } = useForm<ValoresReenvio>({
+    resolver: zodResolver(reenvioSchema),
+    defaultValues: { correo: correo ?? '' },
+  });
+  const { ref, ...campoCorreo } = register('correo');
+
+  const enviar = handleSubmit((valores) => {
+    reenvio.mutate({ correo: valores.correo.trim() });
+  });
+
+  return (
+    <Box component="form" noValidate onSubmit={(evento) => void enviar(evento)}>
+      <Stack spacing={2}>
+        <Typography variant="body2" color="text.secondary">
+          ¿No te llegó? Revisa tu carpeta de correo no deseado o pide un nuevo enlace; el anterior dejará de
+          funcionar.
+        </Typography>
+        {!correo && (
+          <TextField
+            label="Correo"
+            required
+            fullWidth
+            autoComplete="email"
+            inputProps={{ inputMode: 'email' }}
+            inputRef={ref}
+            {...campoCorreo}
+            error={errors.correo !== undefined}
+            helperText={errors.correo?.message ?? 'El correo con el que creaste tu cuenta.'}
+          />
+        )}
+        {reenvio.isSuccess && <Alert severity="success">{reenvio.data?.mensaje ?? MENSAJE_REENVIO_POR_DEFECTO}</Alert>}
+        {reenvio.isError && <Alert severity="error">{mensajeDeError(reenvio.error)}</Alert>}
+        <Button type="submit" variant="outlined" disabled={reenvio.isPending}>
+          Reenviar correo de verificación
+        </Button>
+      </Stack>
+    </Box>
+  );
+}
