+import { screen } from '@testing-library/react';
+import userEvent from '@testing-library/user-event';
+import { HttpResponse, http as mswHttp } from 'msw';
+import { describe, expect, it } from 'vitest';
+import { RUTAS } from '../../../app/rutas';
+import { urlApi } from '../../../test/api';
+import { renderRuta } from '../../../test/renderRuta';
+import { server } from '../../../test/server';
+
+const TOKEN = 'q3kX9vVb0mJ2rT7yLw4nZs8aPe1cHu6dGf5iKo0lMbA';
+const MENSAJE_NEUTRO = 'Si el correo tiene una cuenta pendiente de verificación, te enviaremos un nuevo enlace.';
+
+type RespuestaMock = ReturnType<typeof HttpResponse.json> | Response;
+
+const cuentaActivada = (expedienteExistente = false) =>
+  HttpResponse.json({ id: 'u1', correo: 'ana.ruiz@test.com', estado: 'ACTIVA', expedienteExistente });
+
+const errorApi = (status: number, codigo: string) => HttpResponse.json({ codigo, mensaje: codigo }, { status });
+
+/** Declara el handler de la verificación y devuelve los cuerpos que recibe (una respuesta por llamada). */
+function prepararVerificacion(...respuestas: Array<() => RespuestaMock>): unknown[] {
+  const solicitudes: unknown[] = [];
+  server.use(
+    mswHttp.post(urlApi('/registro/verificar-correo'), async ({ request }) => {
+      solicitudes.push(await request.json());
+      const responder = respuestas[Math.min(solicitudes.length, respuestas.length) - 1];
+      return responder();
+    }),
+  );
+  return solicitudes;
+}
+
+function prepararReenvio(): unknown[] {
+  const solicitudes: unknown[] = [];
+  server.use(
+    mswHttp.post(urlApi('/registro/reenviar-verificacion'), async ({ request }) => {
+      solicitudes.push(await request.json());
+      return HttpResponse.json({ mensaje: MENSAJE_NEUTRO }, { status: 202 });
+    }),
+  );
+  return solicitudes;
+}
+
+const abrirEnlace = (token: string | null = TOKEN) =>
+  renderRuta(token === null ? RUTAS.verificarCorreo : `${RUTAS.verificarCorreo}?token=${token}`);
+
+const tituloResultado = (nombre: string) => screen.findByRole('heading', { level: 2, name: nombre });
+
+describe('VerificarCorreoPage', () => {
+  it('activa la cuenta con el token del enlace y ofrece iniciar sesión (TC-004, TC-005)', async () => {
+    const solicitudes = prepararVerificacion(() => cuentaActivada());
+    abrirEnlace();
+
+    expect(screen.getByRole('heading', { level: 1, name: 'Verificación de correo' })).toBeInTheDocument();
+    expect(await tituloResultado('¡Tu cuenta está activa!')).toBeInTheDocument();
+    expect(screen.getByText(/ya puedes iniciar sesión/i)).toBeInTheDocument();
+    expect(screen.getByRole('link', { name: 'Iniciar sesión' })).toHaveAttribute('href', RUTAS.login);
+    expect(screen.queryByText(/expediente/i)).not.toBeInTheDocument();
+    expect(solicitudes).toEqual([{ token: TOKEN }]);
+  });
+
+  it('muestra "Verificando…" mientras espera la respuesta', async () => {
+    prepararVerificacion(() => cuentaActivada());
+    abrirEnlace();
+
+    expect(await screen.findByText('Estamos verificando tu correo…')).toBeInTheDocument();
+    expect(await tituloResultado('¡Tu cuenta está activa!')).toBeInTheDocument();
+    expect(screen.queryByText('Estamos verificando tu correo…')).not.toBeInTheDocument();
+  });
+
+  it('avisa que la cuenta quedó vinculada al expediente existente (E4)', async () => {
+    prepararVerificacion(() => cuentaActivada(true));
+    abrirEnlace();
+
+    expect(await tituloResultado('¡Tu cuenta está activa!')).toBeInTheDocument();
+    expect(screen.getByText(/vinculamos a tu expediente/i)).toBeInTheDocument();
+  });
+
+  it('con el enlace expirado no activa la cuenta y permite pedir uno nuevo (TC-010, TC-029)', async () => {
+    prepararVerificacion(() => errorApi(410, 'TOKEN_EXPIRADO'));
+    const reenvios = prepararReenvio();
+    const user = userEvent.setup();
+    abrirEnlace();
+
+    expect(await tituloResultado('Enlace expirado')).toBeInTheDocument();
+    expect(screen.getByText(/sigue pendiente de verificación/i)).toBeInTheDocument();
+    expect(screen.queryByText('¡Tu cuenta está activa!')).not.toBeInTheDocument();
+    expect(screen.queryByRole('heading', { name: 'Enlace inválido' })).not.toBeInTheDocument();
+
+    await user.type(screen.getByLabelText(/^Correo/), 'ana.ruiz@test.com');
+    await user.click(screen.getByRole('button', { name: 'Reenviar correo de verificación' }));
+
+    expect(await screen.findByText(MENSAJE_NEUTRO)).toBeInTheDocument();
+    expect(reenvios).toEqual([{ correo: 'ana.ruiz@test.com' }]);
+  });
+
+  it('si la cuenta ya estaba verificada lo indica y lleva al inicio de sesión (TC-027)', async () => {
+    prepararVerificacion(() => errorApi(409, 'CUENTA_YA_VERIFICADA'));
+    abrirEnlace();
+
+    expect(await tituloResultado('Cuenta ya verificada')).toBeInTheDocument();
+    expect(screen.getByText(/ya está verificada/i)).toBeInTheDocument();
+    expect(screen.getByRole('link', { name: 'Ir a iniciar sesión' })).toHaveAttribute('href', RUTAS.login);
+    expect(screen.queryByRole('button', { name: 'Reenviar correo de verificación' })).not.toBeInTheDocument();
+  });
+
+  it('con un token alterado o inexistente muestra un mensaje genérico de enlace inválido (TC-028)', async () => {
+    const solicitudes = prepararVerificacion(() => errorApi(400, 'TOKEN_INVALIDO'));
+    abrirEnlace('inexistente123');
+
+    expect(await tituloResultado('Enlace inválido')).toBeInTheDocument();
+    expect(screen.getByText(/no es válido/i)).toBeInTheDocument();
+    expect(screen.queryByText(/expir/i)).not.toBeInTheDocument();
+    expect(screen.queryByText(/ya está verificada/i)).not.toBeInTheDocument();
+    expect(screen.queryByText('¡Tu cuenta está activa!')).not.toBeInTheDocument();
+    expect(solicitudes).toEqual([{ token: 'inexistente123' }]);
+  });
+
+  it('sin token en el enlace muestra enlace inválido sin llamar a la API', async () => {
+    const solicitudes = prepararVerificacion(() => cuentaActivada());
+    abrirEnlace(null);
+
+    expect(await tituloResultado('Enlace inválido')).toBeInTheDocument();
+    expect(solicitudes).toHaveLength(0);
+  });
+
+  it('ante un error inesperado muestra el mensaje genérico y permite reintentar con el mismo enlace', async () => {
+    const solicitudes = prepararVerificacion(
+      () => new HttpResponse(null, { status: 500 }),
+      () => cuentaActivada(),
+    );
+    const user = userEvent.setup();
+    abrirEnlace();
+
+    expect(await tituloResultado('No pudimos verificar tu correo')).toBeInTheDocument();
+    expect(screen.getByText('Ocurrió un error inesperado. Intenta de nuevo más tarde.')).toBeInTheDocument();
+
+    await user.click(screen.getByRole('button', { name: 'Reintentar' }));
+
+    expect(await tituloResultado('¡Tu cuenta está activa!')).toBeInTheDocument();
+    expect(solicitudes).toEqual([{ token: TOKEN }, { token: TOKEN }]);
+  });
+
+  it('consume el enlace una sola vez al abrir la página', async () => {
+    const solicitudes = prepararVerificacion(() => cuentaActivada());
+    abrirEnlace();
+
+    expect(await tituloResultado('¡Tu cuenta está activa!')).toBeInTheDocument();
+    expect(solicitudes).toHaveLength(1);
+  });
+});
