+import { useMutation } from '@tanstack/react-query';
+import { http, type ApiError, type HttpClient } from '../../../api/http';
+import type { components } from '../../../api/schema';
+
+export type SolicitudVerificacion = components['schemas']['VerificarCorreoDto'];
+export type RespuestaVerificacion = components['schemas']['VerificacionRespuestaDto'];
+
+export const VERIFICAR_CORREO_PATH = '/registro/verificar-correo';
+
+/** POST /registro/verificar-correo: consume el token del enlace, activa la cuenta y la vincula a su expediente (HU-001). */
+export function useVerificarCorreoMutation(cliente: HttpClient = http) {
+  return useMutation<RespuestaVerificacion, ApiError | Error, SolicitudVerificacion>({
+    mutationFn: (solicitud) => cliente.post<RespuestaVerificacion>(VERIFICAR_CORREO_PATH, solicitud),
+  });
+}
