+import { ApiError } from '../../api/http';
+import { CODIGOS_ERROR } from '../../shared/errors/mensajesError';
+
+/** Cómo termina un intento fallido de verificar el correo (POST /registro/verificar-correo). */
+export type FalloVerificacion = 'expirado' | 'invalido' | 'ya-verificada' | 'error';
+
+/** Token del parámetro `token` del enlace; null si falta o viene vacío. */
+export function leerTokenVerificacion(valor: string | null): string | null {
+  const token = valor?.trim() ?? '';
+  return token === '' ? null : token;
+}
+
+/**
+ * Traduce el error de la verificación al estado que muestra la pantalla. Lo que no es un resultado definitivo
+ * del enlace (red, 5xx, conflicto momentáneo, límite de frecuencia) queda como `error`, que se puede reintentar.
+ */
+export function clasificarErrorVerificacion(error: unknown): FalloVerificacion {
+  if (!(error instanceof ApiError)) return 'error';
+  switch (error.codigo) {
+    case CODIGOS_ERROR.TOKEN_EXPIRADO:
+      return 'expirado';
+    case CODIGOS_ERROR.CUENTA_YA_VERIFICADA:
+      return 'ya-verificada';
+    case CODIGOS_ERROR.TOKEN_INVALIDO:
+    case CODIGOS_ERROR.VALIDACION:
+      return 'invalido';
+    default:
+      return 'error';
+  }
+}
