+/** http:// solo se tolera en producción hacia el propio equipo (probar la imagen de producción en local). */
+const LOOPBACK_HTTP = /^http:\/\/(localhost|127\.0\.0\.1|\[::1\])(:\d+)?(\/|$)/i;
+
+/**
+ * Valida VITE_API_BASE_URL. En producción las credenciales y los tokens solo viajan por HTTPS (HU-002 I13): se
+ * acepta una URL https:// o una ruta relativa del mismo dominio (p. ej. /api/v1 detrás del Load Balancer), y se
+ * rechaza cualquier http:// que no sea loopback.
+ */
+export function resolverBaseUrl(valor: string | undefined, produccion: boolean): string {
+  const base = (valor ?? '').trim();
+  if (produccion && /^http:\/\//i.test(base) && !LOOPBACK_HTTP.test(base)) {
+    throw new Error(
+      `VITE_API_BASE_URL debe usar HTTPS en producción (o una ruta relativa del mismo dominio): "${base}".`,
+    );
+  }
+  return base;
+}
