+import type { ReactNode } from 'react';
+import { Navigate, Outlet, useLocation } from 'react-router-dom';
+import { PantallaCargando } from '../shared/components/PantallaCargando';
+import { useAuth } from './useAuth';
+
+interface RedirigirSiAutenticadoProps {
+  /** Pantalla para visitantes sin sesión; si se omite se renderizan las rutas hijas (<Outlet />). */
+  children?: ReactNode;
+}
+
+/**
+ * Para pantallas de visitante como el login (HU-002 I11): con una sesión válida manda a la pantalla inicial del
+ * rol (la rutaInicial del backend). También lleva ahí justo después de iniciar sesión. Mientras se restaura la
+ * sesión al recargar muestra la pantalla de carga para no mostrar el formulario a un usuario ya autenticado.
+ */
+export function RedirigirSiAutenticado({ children }: RedirigirSiAutenticadoProps) {
+  const { estado, rutaInicial } = useAuth();
+  const location = useLocation();
+
+  if (estado === 'cargando') {
+    return <PantallaCargando />;
+  }
+  // Si la ruta inicial es la actual (rol desconocido → login) se muestra la pantalla en vez de redirigir en bucle.
+  if (estado === 'autenticado' && rutaInicial && rutaInicial !== location.pathname) {
+    return <Navigate to={rutaInicial} replace />;
+  }
+  return children ? <>{children}</> : <Outlet />;
+}
