@@ -0,0 +1,38 @@
+import { ApiError, REFRESH_PATH, http, type HttpClient } from '../api/http';
+import type { components } from '../api/schema';
+import type { Sesion } from './types';
+
+export type RespuestaLogin = components['schemas']['LoginResponseDto'];
+export type RespuestaRefresh = components['schemas']['RefreshResponseDto'];
+
+/** Sesión de la SPA a partir de la respuesta de /auth/login o /auth/refresh (mismo contrato). */
+export function aSesion(respuesta: RespuestaLogin | RespuestaRefresh): Sesion {
+  const { usuario } = respuesta;
+  return {
+    accessToken: respuesta.accessToken,
+    usuario: {
+      id: usuario.id,
+      correo: usuario.correo,
+      nombres: usuario.nombres,
+      apellidos: usuario.apellidos,
+      rol: respuesta.rol,
+    },
+    rutaInicial: respuesta.rutaInicial,
+  };
+}
+
+/**
+ * Restaura la sesión al recargar la página: POST /auth/refresh con la cookie httpOnly del refresh token. Devuelve
+ * null si no hay sesión (401) y propaga cualquier otro error (AuthProvider arranca anónimo en ambos casos).
+ */
+export function crearRestauradorSesion(cliente: HttpClient = http): () => Promise<Sesion | null> {
+  return async () => {
+    try {
+      const respuesta = await cliente.post<RespuestaRefresh>(REFRESH_PATH, undefined, { sinReintento: true });
+      return aSesion(respuesta);
+    } catch (error) {
+      if (error instanceof ApiError && error.status === 401) return null;
+      throw error;
+    }
+  };
+}
