+  it('mientras se restaura la sesión muestra la pantalla de carga sin contenido ni redirección', async () => {
+    const router = renderGuard('/solo-admin', { restaurarSesion: () => new Promise<Sesion | null>(() => undefined) });
+
+    expect(await screen.findByLabelText('Cargando')).toBeInTheDocument();
+    expect(screen.queryByText('Zona de administración')).not.toBeInTheDocument();
+    expect(router.state.location.pathname).toBe('/solo-admin');
+  });
+});
