+import { screen, waitFor } from '@testing-library/react';
+import userEvent, { type UserEvent } from '@testing-library/user-event';
+import { HttpResponse, http as mswHttp } from 'msw';
+import { describe, expect, it } from 'vitest';
+import type { components } from '../../api/schema';
+import { RUTAS } from '../../app/rutas';
+import { API_URL, urlApi } from '../../test/api';
+import { renderRuta } from '../../test/renderRuta';
+import { server } from '../../test/server';
+
+type RespuestaNeutraDto = components['schemas']['RespuestaNeutraDto'];
+
+/** Mensaje neutro que responde el backend (password-recovery.errors.ts) y que la pantalla muestra siempre. */
+const MENSAJE_CONFIRMACION = 'Si el correo está registrado, te enviaremos un enlace para restablecer tu contraseña.';
+const CORREO_REGISTRADO = 'qa.user01@test.local';
+const CORREO_NO_REGISTRADO = 'no.existe.9f3a@test.local';
+
+type RespuestaMock = ReturnType<typeof HttpResponse.json> | Response;
+
+const aceptada = (): RespuestaMock =>
+  HttpResponse.json<RespuestaNeutraDto>({ mensaje: MENSAJE_CONFIRMACION }, { status: 202 });
+const limiteExcedido = (): RespuestaMock =>
+  HttpResponse.json(
+    { codigo: 'DEMASIADAS_SOLICITUDES', mensaje: 'Demasiadas solicitudes. Intenta más tarde.' },
+    { status: 429 },
+  );
+
+interface PeticionSolicitud {
+  cuerpo: unknown;
+  url: string;
+  credentials: RequestCredentials;
+}
+
+/**
+ * Handler de POST /auth/password/solicitar. Responde en orden cada respuesta de `respuestas` (la última se repite;
+ * sin respuestas, el 202 neutro) y devuelve las peticiones recibidas.
+ */
+function mockSolicitar(...respuestas: (() => RespuestaMock)[]): PeticionSolicitud[] {
+  const peticiones: PeticionSolicitud[] = [];
+  server.use(
+    mswHttp.post(urlApi('/auth/password/solicitar'), async ({ request }) => {
+      peticiones.push({ cuerpo: await request.json(), url: request.url, credentials: request.credentials });
+      const responder = respuestas[Math.min(peticiones.length - 1, respuestas.length - 1)];
+      return responder ? responder() : aceptada();
+    }),
+  );
+  return peticiones;
+}
+
+const campoCorreo = () => screen.getByLabelText(/^Correo/);
+const botonEnviar = () => screen.getByRole('button', { name: 'Enviar' });
+const confirmacion = () => screen.queryByRole('status');
+
+async function abrir() {
+  const render = renderRuta(RUTAS.olvideContrasena);
+  await screen.findByRole('heading', { level: 1, name: 'Olvidé mi contraseña' });
+  return render;
+}
+
+/** Escribe `correo` (reemplazando lo que hubiera) y pulsa Enviar cuando el envío anterior ya terminó. */
+async function solicitar(user: UserEvent, correo: string) {
+  await user.clear(campoCorreo());
+  if (correo !== '') await user.type(campoCorreo(), correo);
+  await waitFor(() => expect(botonEnviar()).toBeEnabled());
+  await user.click(botonEnviar());
+}
+
+describe('OlvideContrasenaPage: solicitud del enlace', () => {
+  it('con un correo registrado muestra el mensaje genérico de confirmación (TC-001)', async () => {
+    const peticiones = mockSolicitar();
+    const user = userEvent.setup();
+    const { router } = await abrir();
+
+    await solicitar(user, CORREO_REGISTRADO);
+
+    expect(await screen.findByRole('status')).toHaveTextContent(MENSAJE_CONFIRMACION);
+    expect(peticiones).toHaveLength(1);
+    expect(peticiones[0].cuerpo).toEqual({ correo: CORREO_REGISTRADO });
+    expect(peticiones[0].url).toBe(`${API_URL}/auth/password/solicitar`);
+    expect(router.state.location.pathname).toBe(RUTAS.olvideContrasena);
+    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
+  });
+
+  it('envía el correo sin espacios alrededor', async () => {
+    const peticiones = mockSolicitar();
+    const user = userEvent.setup();
+    await abrir();
+
+    await solicitar(user, `  ${CORREO_REGISTRADO} `);
+
+    expect(await screen.findByRole('status')).toHaveTextContent(MENSAJE_CONFIRMACION);
+    expect(peticiones.map((p) => p.cuerpo)).toEqual([{ correo: CORREO_REGISTRADO }]);
+  });
+
+  it('muestra exactamente el mismo texto con un correo registrado y con uno no registrado (TC-007, TC-009)', async () => {
+    const peticiones = mockSolicitar();
+    const user = userEvent.setup();
+
+    const registrado = await abrir();
+    await solicitar(user, CORREO_REGISTRADO);
+    const textoRegistrado = (await screen.findByRole('status')).textContent;
+    const pantallaRegistrado = registrado.container.textContent?.replace(CORREO_REGISTRADO, '');
+    registrado.unmount();
+
+    const noRegistrado = await abrir();
+    await solicitar(user, CORREO_NO_REGISTRADO);
+    const textoNoRegistrado = (await screen.findByRole('status')).textContent;
+    const pantallaNoRegistrado = noRegistrado.container.textContent?.replace(CORREO_NO_REGISTRADO, '');
+
+    expect(textoRegistrado).toBe(MENSAJE_CONFIRMACION);
+    expect(textoNoRegistrado).toBe(textoRegistrado);
+    expect(pantallaNoRegistrado).toBe(pantallaRegistrado);
+    expect(screen.getByRole('status')).not.toHaveTextContent(/no (está|existe)|no registrad/i);
+    expect(peticiones.map((p) => p.cuerpo)).toEqual([{ correo: CORREO_REGISTRADO }, { correo: CORREO_NO_REGISTRADO }]);
+  });
+
+  it('con el límite de frecuencia (429) muestra el mismo mensaje y ningún error (TC-023)', async () => {
