@@ -0,0 +1,99 @@
+import { zodResolver } from '@hookform/resolvers/zod';
+import Alert from '@mui/material/Alert';
+import Box from '@mui/material/Box';
+import Button from '@mui/material/Button';
+import Stack from '@mui/material/Stack';
+import TextField from '@mui/material/TextField';
+import { useState } from 'react';
+import { useForm } from 'react-hook-form';
+import { ApiError } from '../../../api/http';
+import { mensajeDeError } from '../../../shared/errors/mensajesError';
+import {
+  MENSAJE_SOLICITUD_RESTABLECIMIENTO,
+  VALORES_INICIALES_SOLICITUD,
+  solicitarRestablecimientoSchema,
+  type SolicitudRestablecimiento,
+  type ValoresSolicitudRestablecimiento,
+} from '../solicitarRestablecimiento';
+
+interface SolicitarRestablecimientoFormProps {
+  /** Envía la solicitud ya validada. Si la promesa se rechaza, el formulario muestra el error traducido. */
+  onSolicitar: (solicitud: SolicitudRestablecimiento) => Promise<void>;
+}
+
+/**
+ * Formulario "Olvidé mi contraseña" (HU-003) con react-hook-form + zod: correo obligatorio y con formato válido;
+ * si la validación falla no se envía la petición. Tras enviar muestra siempre el mismo mensaje de confirmación
+ * (fijo, no el texto de la respuesta), exista o no el correo. Solo los fallos ajenos al correo (validación del
+ * backend, red, 5xx) muestran un error. El correo se conserva para poder pedir otro enlace.
+ */
+export function SolicitarRestablecimientoForm({ onSolicitar }: SolicitarRestablecimientoFormProps) {
+  const {
+    register,
+    handleSubmit,
+    setError,
+    formState: { errors, isSubmitting },
+  } = useForm<ValoresSolicitudRestablecimiento>({
+    resolver: zodResolver(solicitarRestablecimientoSchema),
+    defaultValues: VALORES_INICIALES_SOLICITUD,
+  });
+  const [confirmada, setConfirmada] = useState(false);
+  const [errorServidor, setErrorServidor] = useState<{ error: unknown } | null>(null);
+
+  /** Coloca junto al correo los mensajes de `campos.correo` del ErrorDto (VALIDACION). */
+  const mostrarErrorDeCampo = (error: unknown) => {
+    const mensajes = error instanceof ApiError ? error.campos?.correo : undefined;
+    if (mensajes && mensajes.length > 0) {
+      setError('correo', { type: 'server', message: mensajes.join(' ') });
+    }
+  };
+
+  const enviar = handleSubmit(
+    async (valores) => {
+      setConfirmada(false);
+      setErrorServidor(null);
+      try {
+        await onSolicitar({ correo: valores.correo.trim() });
+        setConfirmada(true);
+      } catch (error) {
+        mostrarErrorDeCampo(error);
+        setErrorServidor({ error });
+      }
+    },
+    () => {
+      setConfirmada(false);
+      setErrorServidor(null);
+    },
+  );
+
+  const { ref, ...campoCorreo } = register('correo');
+
+  return (
+    <Box component="form" noValidate onSubmit={(evento) => void enviar(evento)}>
+      <Stack spacing={2}>
+        <TextField
+          label="Correo"
+          required
+          fullWidth
+          autoComplete="email"
+          inputProps={{ inputMode: 'email' }}
+          inputRef={ref}
+          {...campoCorreo}
+          error={errors.correo !== undefined}
+          helperText={errors.correo?.message}
+        />
+
+        {confirmada && (
+          <Alert severity="success" role="status">
+            {MENSAJE_SOLICITUD_RESTABLECIMIENTO}
+          </Alert>
+        )}
+        {errorServidor !== null && <Alert severity="error">{mensajeDeError(errorServidor.error)}</Alert>}
+
+        <Button type="submit" variant="contained" size="large" disabled={isSubmitting}>
+          Enviar
+        </Button>
+      </Stack>
+    </Box>
+  );
+}
