+import { QueryClientProvider } from '@tanstack/react-query';
+import { renderHook, waitFor } from '@testing-library/react';
+import type { ReactNode } from 'react';
+import { describe, expect, it, vi } from 'vitest';
+import { ApiError, type HttpClient } from '../../../api/http';
+import { createQueryClient } from '../../../app/queryClient';
+import { MENSAJE_SOLICITUD_RESTABLECIMIENTO } from '../solicitarRestablecimiento';
+import {
+  SOLICITAR_RESTABLECIMIENTO_PATH,
+  useSolicitarRestablecimientoMutation,
+} from './useSolicitarRestablecimientoMutation';
+
+/** Cliente HTTP falso: solo `post`, que es lo único que usa el hook. */
+function clienteFalso(post: ReturnType<typeof vi.fn>): HttpClient {
+  return { post } as unknown as HttpClient;
+}
+
+function wrapper({ children }: { children: ReactNode }) {
+  return <QueryClientProvider client={createQueryClient()}>{children}</QueryClientProvider>;
+}
+
+describe('useSolicitarRestablecimientoMutation', () => {
+  it('envía el correo a POST /auth/password/solicitar sin pasar por el refresh', async () => {
+    const post = vi.fn().mockResolvedValue({ mensaje: MENSAJE_SOLICITUD_RESTABLECIMIENTO });
+    const { result } = renderHook(() => useSolicitarRestablecimientoMutation(clienteFalso(post)), { wrapper });
+
+    await expect(result.current.mutateAsync({ correo: 'qa.user01@test.local' })).resolves.toEqual({
+      mensaje: MENSAJE_SOLICITUD_RESTABLECIMIENTO,
+    });
+    expect(post).toHaveBeenCalledWith(
+      SOLICITAR_RESTABLECIMIENTO_PATH,
+      { correo: 'qa.user01@test.local' },
+      { sinReintento: true },
+    );
+    expect(SOLICITAR_RESTABLECIMIENTO_PATH).toBe('/auth/password/solicitar');
+  });
+
+  it('trata el 429 del límite de frecuencia como la misma respuesta neutra (TC-023, TC-024)', async () => {
+    const post = vi
+      .fn()
+      .mockRejectedValue(new ApiError(429, { codigo: 'DEMASIADAS_SOLICITUDES', mensaje: 'Too many requests' }));
+    const { result } = renderHook(() => useSolicitarRestablecimientoMutation(clienteFalso(post)), { wrapper });
+
+    await expect(result.current.mutateAsync({ correo: 'qa.user01@test.local' })).resolves.toEqual({
+      mensaje: MENSAJE_SOLICITUD_RESTABLECIMIENTO,
+    });
+    await waitFor(() => expect(result.current.isSuccess).toBe(true));
+  });
+
+  it('propaga los demás errores (validación del backend, red)', async () => {
+    const error = new ApiError(400, { codigo: 'VALIDACION', mensaje: 'Datos inválidos.' });
+    const post = vi.fn().mockRejectedValue(error);
+    const { result } = renderHook(() => useSolicitarRestablecimientoMutation(clienteFalso(post)), { wrapper });
+
+    await expect(result.current.mutateAsync({ correo: 'usuario@' })).rejects.toBe(error);
+    await waitFor(() => expect(result.current.isError).toBe(true));
+  });
+});
