+import { useMutation } from '@tanstack/react-query';
+import { http, type ApiError, type HttpClient } from '../../../api/http';
+import {
+  MENSAJE_SOLICITUD_RESTABLECIMIENTO,
+  esLimiteDeFrecuencia,
+  type RespuestaNeutra,
+  type SolicitudRestablecimiento,
+} from '../solicitarRestablecimiento';
+
+export const SOLICITAR_RESTABLECIMIENTO_PATH = '/auth/password/solicitar';
+
+/**
+ * POST /auth/password/solicitar (HU-003). El backend responde siempre 202 con un mensaje neutro; si limita la
+ * frecuencia (429) la mutación resuelve con esa misma respuesta neutra, para que la pantalla no cambie
+ * (TC-023, TC-024). Es un endpoint público: sin reintento vía /auth/refresh.
+ */
+export function useSolicitarRestablecimientoMutation(cliente: HttpClient = http) {
+  return useMutation<RespuestaNeutra, ApiError | Error, SolicitudRestablecimiento>({
+    mutationFn: async (solicitud) => {
+      try {
+        return await cliente.post<RespuestaNeutra>(SOLICITAR_RESTABLECIMIENTO_PATH, solicitud, { sinReintento: true });
+      } catch (error) {
+        if (esLimiteDeFrecuencia(error)) return { mensaje: MENSAJE_SOLICITUD_RESTABLECIMIENTO };
+        throw error;
+      }
+    },
+  });
+}
