+import { describe, expect, it } from 'vitest';
+import { ApiError, CODIGO_ERROR_RED } from '../../api/http';
+import { MENSAJE_CORREO_INVALIDO, MENSAJE_CORREO_OBLIGATORIO } from '../../shared/validation/correo';
+import {
+  CORREO_MAX_RESTABLECIMIENTO,
+  MENSAJE_CORREO_MAX_RESTABLECIMIENTO,
+  esLimiteDeFrecuencia,
+  solicitarRestablecimientoSchema,
+} from './solicitarRestablecimiento';
+
+function erroresDe(correo: unknown): string[] {
+  const resultado = solicitarRestablecimientoSchema.safeParse({ correo });
+  return resultado.success ? [] : resultado.error.issues.map((issue) => issue.message);
+}
+
+describe('solicitarRestablecimientoSchema', () => {
+  it('acepta un correo válido y lo recorta', () => {
+    expect(solicitarRestablecimientoSchema.parse({ correo: '  qa.user01@test.local ' })).toEqual({
+      correo: 'qa.user01@test.local',
+    });
+  });
+
+  it.each(['', '   '])('con el correo vacío (%j) exige el correo (TC-011)', (correo) => {
+    expect(erroresDe(correo)).toEqual([MENSAJE_CORREO_OBLIGATORIO]);
+  });
+
+  it.each(['usuario', 'usuario@', '@dominio.com', 'usu ario@dominio.com', 'usuario.dominio.com'])(
+    'rechaza el formato inválido %j (TC-012)',
+    (correo) => {
+      expect(erroresDe(correo)).toEqual([MENSAJE_CORREO_INVALIDO]);
+    },
+  );
+
+  it('respeta el máximo de caracteres del backend', () => {
+    const dominio = '@test.local';
+    const alLimite = `${'a'.repeat(CORREO_MAX_RESTABLECIMIENTO - dominio.length)}${dominio}`;
+
+    expect(erroresDe(alLimite)).toEqual([]);
+    expect(erroresDe(`a${alLimite}`)).toEqual([MENSAJE_CORREO_MAX_RESTABLECIMIENTO]);
+  });
+});
+
+describe('esLimiteDeFrecuencia', () => {
+  it('reconoce el 429 del backend', () => {
+    expect(esLimiteDeFrecuencia(new ApiError(429, { codigo: 'DEMASIADAS_SOLICITUDES', mensaje: 'x' }))).toBe(true);
+  });
+
+  it.each([
+    ['un 400 de validación', new ApiError(400, { codigo: 'VALIDACION', mensaje: 'x' })],
+    ['un 500', new ApiError(500, { codigo: 'ERROR_INTERNO', mensaje: 'x' })],
+    ['un error de red', new ApiError(0, { codigo: CODIGO_ERROR_RED, mensaje: 'x' })],
+    ['un error cualquiera', new Error('x')],
+  ])('no confunde %s con el límite', (_caso, error) => {
+    expect(esLimiteDeFrecuencia(error)).toBe(false);
+  });
+});
