+import { z } from 'zod';
+import { ApiError } from '../../api/http';
+import type { components } from '../../api/schema';
+import { correoSchema } from '../../shared/validation/correo';
+
+export type SolicitudRestablecimiento = components['schemas']['SolicitarRestablecimientoDto'];
+export type RespuestaNeutra = components['schemas']['RespuestaNeutraDto'];
+
+/**
+ * Confirmación de la solicitud (HU-003). Es la misma que responde el backend (password-recovery.errors.ts) y la
+ * pantalla la muestra siempre igual: con un correo registrado o no, y también si el backend limita la frecuencia,
+ * para no revelar qué correos existen.
+ */
+export const MENSAJE_SOLICITUD_RESTABLECIMIENTO =
+  'Si el correo está registrado, te enviaremos un enlace para restablecer tu contraseña.';
+
+/** Mismo máximo que SolicitarRestablecimientoDto del backend. */
+export const CORREO_MAX_RESTABLECIMIENTO = 254;
+export const MENSAJE_CORREO_MAX_RESTABLECIMIENTO = `El correo admite como máximo ${CORREO_MAX_RESTABLECIMIENTO} caracteres.`;
+
+/** Formulario "Olvidé mi contraseña": correo obligatorio y con formato válido (TC-011, TC-012). */
+export const solicitarRestablecimientoSchema = z.object({
+  correo: correoSchema.refine(
+    (correo) => correo.length <= CORREO_MAX_RESTABLECIMIENTO,
+    MENSAJE_CORREO_MAX_RESTABLECIMIENTO,
+  ),
+});
+
+/** Valores tal como se capturan en el formulario. */
+export type ValoresSolicitudRestablecimiento = z.input<typeof solicitarRestablecimientoSchema>;
+
+export const VALORES_INICIALES_SOLICITUD: ValoresSolicitudRestablecimiento = { correo: '' };
+
+/** 429 del backend: se pasó el límite de solicitudes (por IP). Se trata como la respuesta neutra. */
+export function esLimiteDeFrecuencia(error: unknown): boolean {
+  return error instanceof ApiError && error.status === 429;
+}
